for cid, obj in P.items():
    with open(os.path.join(BASE, cid+".json"), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)

# assertions
ids=["LY-211","LY-212","LY-215","LY-216","LY-217","LY-218","LY-219","LY-220","LY-221","LY-222","LY-227","LY-228","LY-230","LY-231","LY-232","LY-234","LY-235","LY-237","LY-240","LY-241"]
assert len(P)==len(ids)==20
for cid in ids:
    p=os.path.join(BASE, cid+".json")
    d=json.load(open(p, encoding="utf-8"))
    assert d["case_id"]==cid and os.path.basename(p)==cid+".json"
    for k in ["case_id","prediction_text","basis","confidence","trigger"]:
        assert k in d, (cid,k)
    for k in ["changed_main","reserve_used","disputed","reason"]:
        assert k in d["trigger"], (cid,k)
    assert 0<=d["confidence"]<=1
print("written", len(ids))
cm=sum(1 for v in P.values() if v["trigger"]["changed_main"])
ru=sum(1 for v in P.values() if v["trigger"]["reserve_used"])
di=sum(1 for v in P.values() if v["trigger"]["disputed"])
print("changed_main",cm,"reserve_used",ru,"disputed",di)
